import torch
from torch.utils.cpp_extension import load_inline

# CUDA kernel implementation
cuda_source = """
#include <cuda_fp16.h>
#include <cuda_runtime.h>

__global__ void layer_norm_kernel(
    const half* __restrict__ input,
    half* __restrict__ output,
    const half* __restrict__ weight,
    const half* __restrict__ bias,
    const float* __restrict__ mean,
    const float* __restrict__ rstd,
    int64_t total_elements,
    int64_t normalized_elements
) {
    // Each thread handles one element
    int64_t idx = blockIdx.x * blockDim.x + threadIdx.x;

    if (idx >= total_elements) return;

    // Calculate which normalized dimension this element belongs to
    int64_t norm_idx = idx % normalized_elements;

    // Get the mean and reciprocal standard deviation for this normalized dimension
    float cur_mean = mean[idx / normalized_elements];
    float cur_rstd = rstd[idx / normalized_elements];

    // Perform layer normalization: (x - mean) / std * weight + bias
    float val = __half2float(input[idx]);
    float normalized_val = (val - cur_mean) * cur_rstd;
    float result = normalized_val * __half2float(weight[norm_idx]) + __half2float(bias[norm_idx]);

    output[idx] = __float2half(result);
}

// Helper kernel to compute mean and variance
__global__ void compute_stats_kernel(
    const half* __restrict__ input,
    float* __restrict__ mean,
    float* __restrict__ variance,
    int64_t total_elements,
    int64_t normalized_elements
) {
    extern __shared__ float shared_data[];

    int64_t batch_idx = blockIdx.x;
    int64_t tid = threadIdx.x;

    if (batch_idx >= total_elements / normalized_elements) return;

    // Initialize shared memory
    float* shared_sum = shared_data;
    float* shared_sum_sq = shared_data + blockDim.x;

    shared_sum[tid] = 0.0f;
    shared_sum_sq[tid] = 0.0f;

    // Each thread processes multiple elements
    float sum = 0.0f;
    float sum_sq = 0.0f;

    for (int64_t i = tid; i < normalized_elements; i += blockDim.x) {
        int64_t idx = batch_idx * normalized_elements + i;
        float val = __half2float(input[idx]);
        sum += val;
        sum_sq += val * val;
    }

    shared_sum[tid] = sum;
    shared_sum_sq[tid] = sum_sq;
    __syncthreads();

    // Reduction in shared memory
    for (int64_t stride = blockDim.x / 2; stride > 0; stride >>= 1) {
        if (tid < stride) {
            shared_sum[tid] += shared_sum[tid + stride];
            shared_sum_sq[tid] += shared_sum_sq[tid + stride];
        }
        __syncthreads();
    }

    if (tid == 0) {
        float batch_mean = shared_sum[0] / normalized_elements;
        float batch_var = shared_sum_sq[0] / normalized_elements - batch_mean * batch_mean;
        float batch_rstd = rsqrtf(batch_var + 1e-5f);  // Add epsilon for numerical stability

        mean[batch_idx] = batch_mean;
        variance[batch_idx] = batch_rstd;
    }
}

// Main function to launch kernels
void layer_norm_forward(
    const half* input,
    half* output,
    const half* weight,
    const half* bias,
    float* mean,
    float* rstd,
    int64_t total_elements,
    int64_t normalized_elements
) {
    // First compute statistics
    int64_t num_batches = total_elements / normalized_elements;
    int64_t block_size = 256;
    int64_t grid_size = (num_batches + block_size - 1) / block_size;

    size_t shared_mem_size = 2 * block_size * sizeof(float);
    compute_stats_kernel<<<grid_size, block_size, shared_mem_size>>>(
        input, mean, rstd, total_elements, normalized_elements
    );

    // Then apply normalization
    grid_size = (total_elements + block_size - 1) / block_size;
    layer_norm_kernel<<<grid_size, block_size>>>(
        input, output, weight, bias, mean, rstd, total_elements, normalized_elements
    );
}
"""

# Python wrapper
def create_layer_norm_kernel():
    # Compile the CUDA extension
    module = load_inline(
        name="layer_norm_ext",
        cpp_sources=[],
        cuda_sources=[cuda_source],
        functions=["layer_norm_forward"],
        verbose=True
    )
    return module

# Create the module
layer_norm_module = create_layer_norm_kernel()

class ModelNew(torch.nn.Module):
    def __init__(self, normalized_shape):
        super(ModelNew, self).__init__()
        self.normalized_shape = normalized_shape
        self.weight = torch.nn.Parameter(torch.ones(normalized_shape, dtype=torch.float16))
        self.bias = torch.nn.Parameter(torch.zeros(normalized_shape, dtype=torch.float16))

    def forward(self, x):
        # Ensure input is contiguous and float16
        x = x.contiguous().to(torch.float16)

        # Prepare tensors for CUDA kernel
        total_elements = x.numel()
        normalized_elements = 1
        for dim in self.normalized_shape:
            normalized_elements *= dim

        # Allocate output tensor
        output = torch.empty_like(x)

        # Allocate mean and rstd tensors
        num_batches = total_elements // normalized_elements
        mean = torch.empty(num_batches, dtype=torch.float32, device=x.device)
        rstd = torch.empty(num_batches, dtype=torch.float32, device=x.device)

        # Launch CUDA kernel
        layer_norm_module.layer_norm_forward(
            x.data_ptr(),
            output.data_ptr(),
            self.weight.data_ptr(),
            self.bias.data_ptr(),
            mean.data_ptr(),
            rstd.data_ptr(),
            total_elements,
            normalized_elements
        )

        return output

# Test function
def get_inputs():
    batch_size = 16
    features = 64
    dim1 = 256
    dim2 = 256
    x = torch.rand(batch_size, features, dim1, dim2, dtype=torch.float16)
    return [x]

def get_init_inputs():
    return [(64, 256, 256)]
